<script setup lang="ts">
import { ref,onMounted } from 'vue';import { ElButton } from 'element-plus';import { useDesktop } from './store.ts';
const store=useDesktop(),result=ref<Record<string,unknown>|null>(null),busy=ref(false),error=ref(''),threadId=ref(''),includeDeliveryGates=ref(false);
const labels:Record<string,string>={passed:'通过',blocked:'阻断',unknown:'未知',not_checked:'未检查'};
const names:Record<string,string>={database:'本应用数据库',connection:'来源连接',quota:'额度观察',thread:'明确目标会话',goal:'当前 Goal',goal_account_binding:'Goal 账号绑定',automation:'真实任务自动化',worker:'业务进程',authorization:'当前调用权限',delivery_gate_scope:'真实发送证据范围',delivery_account_observation:'当前账号观察',delivery_target_metadata:'目标元数据',delivery_target_creator:'会话创建账号',delivery_goal_relation:'Goal 与目标关联',delivery_turn_metadata:'已持久化轮次',delivery_lock_snapshot:'共享锁快照',delivery_target_execution_binding:'目标执行账号绑定',delivery_goal_execution_binding:'Goal 执行账号绑定',delivery_source_directory_binding:'桌面与元数据来源绑定',delivery_live_target_state:'实时空闲与批准状态',delivery_unique_receipt:'原发送唯一回执',delivery_legacy_directory_binding:'旧进程实际锁目录',delivery_legacy_recovery:'旧版崩溃恢复兼容',delivery_atomic_exclusion:'原子互斥'};
async function run(){busy.value=true;error.value='';try{const params:Record<string,unknown>={includeDeliveryGates:includeDeliveryGates.value};if(threadId.value.trim()){const connection=await store.request('connections.get');params.threadRef={connectionId:connection.connectionId,threadId:threadId.value.trim()};}result.value=await store.request('diagnostics.run',params);}catch(cause){result.value=null;error.value=(cause as Error).message;}finally{busy.value=false;}}
onMounted(run);
</script>
<template><section class="panel"><div class="section-heading"><h2>只读自检</h2><ElButton type="primary" :disabled="busy" @click="run">运行只读诊断</ElButton></div><p class="muted">检查当前连接、额度快照、存储和调用权限；不会刷新额度、推进调度、发送消息或消费卡片。</p><label>明确目标会话（可选）<input v-model="threadId" aria-label="诊断目标会话 ID" placeholder="留空则会话与 Goal 标为未检查" /></label><label><input v-model="includeDeliveryGates" type="checkbox" aria-label="检查真实发送门禁" />检查真实发送门禁（只读元数据，不读取聊天正文或 Goal 内容，不发送）</label><p v-if="result?.deliveryGates" class="notice">真实发送保持关闭。单项通过只表示该项已观察；创建账号相同不等于执行绑定，空闲锁快照不等于持锁。</p><p v-if="error" role="alert" class="notice">{{ error }}</p><p v-if="busy" role="status">正在核对只读状态…</p></section><section v-if="result" class="panel"><div class="section-heading"><h2 id="diagnostic-status">{{ labels[String(result.status)]||'未知' }}</h2><span class="badge">{{ result.source==='fixture'?'模拟证据':'当前只读观察' }}</span></div><p class="muted">观察时间 {{ new Date(String(result.observedAt)).toLocaleString() }}</p><ul class="check-list"><li v-for="check in (result.checks as Array<{id:string;status:string;reason:string;source:string}>)" :key="check.id"><div><strong>{{ names[check.id]||check.id }}</strong><span class="muted mono">{{ check.reason }}</span></div><span class="badge" :class="check.status==='passed'?'good':check.status==='blocked'?'blocked':'unknown'">{{ labels[check.status]||'未知' }}</span></li></ul></section></template>
